  opx_status: (args, ctx) => statusExecute({ change_id: args.change_id }, ctx),
  opx_orch_complete_task_group: (args, ctx) => completeTaskGroupExecute(args, ctx),
  opx_orch_set_unattended: (args, ctx) => setUnattendedExecute(args, ctx),
